import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import * as tf from '@tensorflow/tfjs-core';
import {
  FamilyNameClassifier,
  ModelBundleLoader,
} from '../../src/anthroponym-declension/family-name-classifier';

const TFJS_BACKEND_CPU_FILEPATH = path.join(__dirname, 'custom_tfjs_backend_cpu.js');
const TFJS_BACKEND_CPU_PACKAGE = '@tensorflow/tfjs-backend-cpu';

/**
 * Runs the family name classifier on the CPU backend and returns the names of the kernels it uses.
 */
async function detectUsedKernels(): Promise<string[]> {
  await tf.setBackend('cpu');

  const profileInfo = await tf.profile(async () => {
    const modelBundleLoader = new ModelBundleLoader();
    const familyNameClassifier = new FamilyNameClassifier(modelBundleLoader);
    await familyNameClassifier.classify('шевченко');
  });

  // Ops that tfjs-core implements by combining other ops appear in the profile with the "__op"
  // suffix. They have no backend kernel of their own, so they are left out.
  const kernels = profileInfo.kernelNames.filter(
    (kernelName) => !kernelName.endsWith(tf.OP_SCOPE_SUFFIX),
  );

  // The classifier skips the model for family names in the incorrect predictions cache.
  // Profiling such a name would detect no kernels and produce a backend that can't run the model.
  if (kernels.length === 0) {
    throw new Error('tf.profile() recorded no kernels while running the family name classifier.');
  }

  return kernels;
}

/**
 * Returns the name of the kernel config that the kernel module exports,
 * e.g. "Slice" -> "sliceConfig", "_FusedMatMul" -> "_fusedMatMulConfig".
 */
function getKernelConfigName(kernelName: string): string {
  const prefix = kernelName.startsWith('_') ? '_' : '';
  const name = kernelName.slice(prefix.length);
  return `${prefix}${name.charAt(0).toLowerCase()}${name.slice(1)}Config`;
}

/**
 * Generates a module that registers the CPU backend with the given kernels only.
 */
function generateBackendCpuModule(kernels: string[]): string {
  const lines = [
    '// This file is autogenerated. Do not edit it manually.',
    '// It registers only the CPU kernels the family name classifier uses, which keeps the UMD bundle small.',
    '',
    "import {registerKernel} from '@tensorflow/tfjs-core/dist/base';",
    `export * from '${TFJS_BACKEND_CPU_PACKAGE}/dist/base';`,
  ];

  for (const kernelName of kernels) {
    const importPath = `${TFJS_BACKEND_CPU_PACKAGE}/dist/kernels/${kernelName}`;
    try {
      require.resolve(importPath);
    } catch {
      throw new Error(`Kernel "${kernelName}" is not available in ${TFJS_BACKEND_CPU_PACKAGE}.`);
    }

    const kernelConfigId = `${kernelName}_cpu`;
    lines.push(
      `import {${getKernelConfigName(kernelName)} as ${kernelConfigId}} from '${importPath}';`,
      `registerKernel(${kernelConfigId});`,
    );
  }

  return lines.join('\n') + '\n';
}

async function main(): Promise<void> {
  const kernels = await detectUsedKernels();
  await fs.writeFile(TFJS_BACKEND_CPU_FILEPATH, generateBackendCpuModule(kernels), 'utf-8');
  console.log(`Registered ${kernels.length} CPU kernels: ${kernels.join(', ')}`);
}

void main();
